// Generated by Viscosity: "ps" stored as a struct of arrays (fields a, b).
class __Vsc_ps {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.a = new Float64Array(cap); this.b = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_ps(Math.max(16, v.length / 2)); for (let i = 0; i < v.length; i += 2) c.push(v[i + 0], v[i + 1]); return c; }
  push(v0, v1) { const n = this.length; if (n === this.cap) this.grow(); this.a[n] = v0; this.b[n] = v1; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.a); this.a = t; t = new Float64Array(cap); t.set(this.b); this.b = t; }
}
// viscosity: ps=soa
const ps = new __Vsc_ps();
let n = 0;
while (n < 5000) {
  ps.push(n, n % 7);
  n++;
}
let s = 0;
for (let i = 0; i < ps.length; i++) s += ps.a[i] * ps.b[i];
console.log(s, ps.length);
